INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (1,1,'General English — Beginner (A1)','general-english-beginner-a1','Start speaking English from day one. No previous knowledge needed.','A friendly, structured start to English: alphabet and sounds, essential grammar, everyday vocabulary and guided speaking practice in every lesson. By the end you will handle simple conversations, introduce yourself and understand basic written English.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (2,1,'اللغة الإنجليزية العامة — مبتدئ (A1)','general-english-beginner-a1-ar','ابدأ التحدث بالإنجليزية من اليوم الأول، دون الحاجة لأي معرفة سابقة.','بداية منظمة وودية لتعلّم الإنجليزية: الحروف والأصوات، القواعد الأساسية، مفردات الحياة اليومية وتدريب موجّه على المحادثة في كل درس. في نهاية الدورة ستتمكن من إجراء محادثات بسيطة وتقديم نفسك وفهم النصوص الأساسية.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (3,2,'General English — Elementary (A2)','general-english-elementary-a2','Build everyday fluency: routines, travel, shopping and short stories.','Consolidate the basics and expand into real situations: past tenses, comparisons, travel language and story-telling, with speaking labs every week to turn knowledge into fluent use.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (4,2,'اللغة الإنجليزية العامة — أساسي (A2)','general-english-elementary-a2-ar','طوّر طلاقتك اليومية: الروتين والسفر والتسوق والقصص القصيرة.','رسّخ الأساسيات وتوسّع نحو مواقف واقعية: أزمنة الماضي، المقارنات، لغة السفر وسرد القصص، مع مختبرات محادثة أسبوعية لتحويل المعرفة إلى استخدام طليق.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (5,3,'General English — Intermediate (B1)','general-english-intermediate-b1','Communicate with confidence in work, travel and social life.','Move from understanding to expressing: perfect tenses in context, future plans, opinion language and phrasal verbs, plus listening built from real conversations and weekly debate practice.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (6,3,'اللغة الإنجليزية العامة — متوسط (B1)','general-english-intermediate-b1-ar','تواصل بثقة في العمل والسفر والحياة الاجتماعية.','انتقل من الفهم إلى التعبير: الأزمنة التامة في سياقها، خطط المستقبل، لغة إبداء الرأي والأفعال المركبة، مع تدريبات استماع من محادثات واقعية ومناظرات أسبوعية.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (7,4,'General English — Upper-Intermediate (B2)','general-english-upper-intermediate-b2','Refine your English: nuance, idioms, essays and presentations.','Push towards advanced mastery: full tense control, conditionals, idiomatic language, press reading, structured essay writing and confident presenting — the springboard to C1 and exam courses.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (8,4,'اللغة الإنجليزية العامة — فوق المتوسط (B2)','general-english-upper-intermediate-b2-ar','صقل لغتك الإنجليزية: الدقة والتعابير والمقالات والعروض التقديمية.','اندفع نحو الإتقان المتقدم: تحكم كامل في الأزمنة، الجمل الشرطية، اللغة الاصطلاحية، قراءة الصحافة، كتابة المقالات المنظمة والعرض بثقة — نقطة الانطلاق نحو C1 ودورات الاختبارات.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (9,5,'Business English Essentials','business-english-essentials','Professional emails, meetings, negotiations and interviews.','Hands-on business communication: write emails that get answers, lead meetings, negotiate, present with impact and shine in interviews — finished with a realistic deal-closing case study.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (10,5,'أساسيات الإنجليزية للأعمال','business-english-essentials-ar','رسائل مهنية واجتماعات ومفاوضات ومقابلات عمل.','تواصل مهني تطبيقي: اكتب رسائل تحصل على ردود، أدر الاجتماعات، فاوض، قدّم عروضًا مؤثرة وتألّق في المقابلات — وتُختتم الدورة بدراسة حالة واقعية لإتمام صفقة.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (11,6,'IELTS Exam Preparation','ielts-exam-preparation','A focused 8-week path to Band 7+, with full mock tests.','Live Zoom classes covering all four IELTS papers: proven strategies for Listening and Reading, high-scoring frameworks for Writing Tasks 1 & 2, and Speaking practice with examiner-style feedback, ending in a full timed mock exam.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (12,6,'التحضير لاختبار الآيلتس IELTS','ielts-exam-preparation-ar','مسار مركّز لمدة 8 أسابيع نحو المستوى +7 مع اختبارات تجريبية كاملة.','حصص مباشرة عبر زووم تغطي أقسام الآيلتس الأربعة: استراتيجيات مجرّبة للاستماع والقراءة، وأطر عالية الدرجات لمهمتي الكتابة 1 و2، وتدريب على المحادثة بتقييم يحاكي الممتحنين، وتُختتم باختبار تجريبي كامل بتوقيت رسمي.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (13,7,'TOEFL iBT Preparation','toefl-ibt-preparation','Master the TOEFL iBT format and target 100+.','Section-by-section mastery of the TOEFL iBT: academic reading, lecture listening with note-taking systems, integrated speaking templates and both essay types, ending in a full simulated test with personal feedback.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (14,7,'التحضير لاختبار التوفل TOEFL iBT','toefl-ibt-preparation-ar','أتقن صيغة التوفل iBT واستهدف نتيجة +100.','إتقان قسمًا بقسم لاختبار التوفل iBT: القراءة الأكاديمية، الاستماع للمحاضرات مع أنظمة تدوين الملاحظات، قوالب المحادثة المتكاملة ونوعا المقال، وتُختتم باختبار محاكاة كامل مع تقييم شخصي.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (15,8,'English Conversation Club','english-conversation-club','Free weekly speaking practice — all levels welcome.','A free, friendly space to actually speak: icebreakers, debates, role-plays, movie and music sessions, guided by our teachers. Join any week, at any level, and build real confidence.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (16,8,'نادي المحادثة الإنجليزية','english-conversation-club-ar','تدريب مجاني أسبوعي على المحادثة — جميع المستويات مرحّب بها.','مساحة مجانية وودية للتحدث الفعلي: كسر الجليد، مناظرات، تمثيل أدوار، وجلسات أفلام وموسيقى بإشراف معلمينا. انضم في أي أسبوع وبأي مستوى وابنِ ثقة حقيقية.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (17,9,'English Grammar Masterclass','english-grammar-masterclass','The complete grammar map — from tenses to reported speech.','Six weeks to organised, confident grammar: the full tense system, articles, modals, complex clauses, passive and reported speech — closed by a clinic on the errors Arabic speakers make most.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (18,9,'دورة القواعد الإنجليزية المتقدمة','english-grammar-masterclass-ar','خريطة القواعد الكاملة — من الأزمنة إلى الكلام المنقول.','ستة أسابيع نحو قواعد منظمة وواثقة: منظومة الأزمنة الكاملة، الأدوات، الأفعال الناقصة، الجمل المركبة، المبني للمجهول والكلام المنقول — وتُختتم بعيادة لأكثر أخطاء الناطقين بالعربية شيوعًا.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (19,10,'Academic Writing Skills','academic-writing-skills','Essays, reports and research writing for university success.','From paragraph architecture to a polished final essay: thesis building, cohesion, summarising, paraphrasing and referencing — everything university study demands of your writing.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (20,10,'مهارات الكتابة الأكاديمية','academic-writing-skills-ar','المقالات والتقارير والكتابة البحثية للنجاح الجامعي.','من بناء الفقرة إلى مقال نهائي متقن: بناء الأطروحة، الترابط، التلخيص، إعادة الصياغة والتوثيق — كل ما تتطلبه الدراسة الجامعية من كتابتك.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (21,11,'English for Kids & Teens','english-for-kids-teens','Fun classroom learning: phonics, stories, songs and games.','A joyful classroom method for young learners: phonics, story time, songs, vocabulary games and confidence-building performances, in small groups by age.','en',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (22,11,'الإنجليزية للأطفال والناشئين','english-for-kids-teens-ar','تعلّم صفّي ممتع: صوتيات وقصص وأغانٍ وألعاب.','منهج صفّي مبهج للصغار: الصوتيات، وقت القصة، الأغاني، ألعاب المفردات وعروض تبني الثقة، في مجموعات صغيرة حسب العمر.','ar',NOW(),NOW());
INSERT INTO product_variations (id,products_id,name,slug,short_description,description,langue,created_at,updated_at) VALUES (23,12,'TESOL Teacher Training Certificate','tesol-teacher-training-certificate','Become a certified English teacher in 10 weeks.','Professional TESOL certification: language-learning principles, lesson planning, classroom management, teaching the four skills and assessment — completed with observed teaching practice and a certificate.','en',NOW(),NOW());
