INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (1,'Rana M.','s1.svg','The IELTS course took me from Band 5.5 to 7.5 in two months. The mock tests felt exactly like the real exam.','نقلتني دورة الآيلتس من 5.5 إلى 7.5 خلال شهرين. الاختبارات التجريبية كانت مطابقة تمامًا للاختبار الحقيقي.',1,1,NOW(),NOW());
INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (2,'Lina K.','s2.svg','Business English changed how I write at work — my emails finally get answers. Best career investment I''ve made.','غيّرت دورة إنجليزية الأعمال طريقة كتابتي في العمل — رسائلي أخيرًا تحصل على ردود. أفضل استثمار مهني قمت به.',1,2,NOW(),NOW());
INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (3,'Ahmed H.','s3.svg','I started at A1 knowing almost nothing. One year later I passed B2 and got a scholarship interview — in English.','بدأت من مستوى A1 دون معرفة تُذكر. بعد عام اجتزت B2 وأجريت مقابلة منحة دراسية — بالإنجليزية.',1,3,NOW(),NOW());
INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (4,'Sami F.','s4.svg','The Conversation Club is gold. Free, fun, and the teachers actually correct you kindly. My fluency doubled.','نادي المحادثة كنز حقيقي: مجاني وممتع، والمعلمون يصححون لك بلطف. تضاعفت طلاقتي.',1,4,NOW(),NOW());
INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (5,'Nour T.','s5.svg','TESOL certification here got me my first teaching job within a month of graduating. The observed practice is priceless.','شهادة TESOL من هنا أوصلتني إلى أول وظيفة تدريس خلال شهر من التخرج. التدريب العملي المُقيَّم لا يُقدّر بثمن.',1,5,NOW(),NOW());
INSERT INTO avis_acceuil (id,client,image,avis_en,avis_ar,is_active,`order`,created_at,updated_at) VALUES (6,'Youssef B.','s6.svg','My kids beg to go to English class now. Songs, games, stories — they learn without noticing they''re learning.','أطفالي يتوسلون للذهاب إلى حصة الإنجليزية الآن. أغانٍ وألعاب وقصص — يتعلمون دون أن يشعروا أنهم يتعلمون.',1,6,NOW(),NOW());
INSERT INTO carousels (id,slug_ar,slug_en,description_ar,description_en,image,is_active,`order`,created_at,updated_at) VALUES (1,'أتقن الإنجليزية وافتح عالمك.','Master English. Open Your World.','حصص مباشرة ومعلمون معتمدون ومسارات منظمة من A1 حتى آيلتس +7.','Live classes, certified teachers and structured paths from A1 to IELTS Band 7+.','hero-1.svg',1,1,NOW(),NOW());
INSERT INTO carousels (id,slug_ar,slug_en,description_ar,description_en,image,is_active,`order`,created_at,updated_at) VALUES (2,'تعلّم مع معلمين معتمدين','Learn from Certified Teachers','مجموعات صغيرة وتدريب حقيقي على المحادثة وتقييم يدفعك للأمام كل أسبوع.','Small groups, real speaking practice and feedback that moves you forward every single week.','hero-2.svg',1,2,NOW(),NOW());
