INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('Speaking exam — Foundation: introduce yourself, your family and your daily routine. Describe a typical day using the present simple, then answer three follow-up questions from the examiner.','en','fa',NOW(),NOW());
INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('اختبار المحادثة — المستوى التأسيسي: قدّم نفسك وعائلتك وروتينك اليومي. صف يومًا اعتياديًا باستخدام المضارع البسيط، ثم أجب عن ثلاثة أسئلة متابعة من الممتحن.','ar','fa',NOW(),NOW());
INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('Speaking exam — Fluency: narrate a past experience that changed you, compare two cities you know well, and give your opinion on technology in education with two supporting reasons.','en','fi',NOW(),NOW());
INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('اختبار المحادثة — مستوى الطلاقة: اسرد تجربة سابقة غيّرتك، وقارن بين مدينتين تعرفهما جيدًا، وأبدِ رأيك في التكنولوجيا في التعليم مع سببين داعمين.','ar','fi',NOW(),NOW());
INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('Speaking exam — Proficiency: discuss the impact of globalisation on local cultures. Structure a two-minute argument with an introduction, two supported points and a conclusion.','en','pt',NOW(),NOW());
INSERT INTO sujets (description,lang,type,created_at,updated_at) VALUES ('اختبار المحادثة — مستوى الإتقان: ناقش أثر العولمة على الثقافات المحلية. قدّم حجة لمدة دقيقتين ببنية واضحة: مقدمة ونقطتان مدعومتان وخاتمة.','ar','pt',NOW(),NOW());
