INSERT INTO blogs (id,titre_ar,titre_en,meta_title_ar,meta_title_en,description_ar,description_en,description_short_ar,description_short_en,slug,image,author_ar,author_en,published_date,is_active,views_count,created_at,updated_at) VALUES (1,'خمس عادات لمتعلمي اللغات الناجحين','5 Habits of Highly Successful Language Learners','عادات المتعلمين الناجحين','Successful Learner Habits','من التعرض اليومي للغة إلى التحدث دون خوف من الخطأ — خمس عادات نلاحظها لدى أنجح طلابنا، وكيف تبنيها خطوة بخطوة.','From daily exposure to fearless speaking — five habits we see in our most successful students, and how to build each one step by step.','خمس عادات تصنع الفرق في رحلة تعلمك.','Five habits that transform your learning journey.','5-habits-successful-language-learners','blog-1.svg','فريق أب سكيلز','Upskills Team',CURDATE(),1,0,NOW(),NOW());
INSERT INTO articles (id,titre_ar,titre_en,meta_title_ar,meta_title_en,description_ar,description_en,description_short_ar,description_short_en,slug,image,author_ar,author_en,published_date,is_active,views_count,created_at,updated_at) VALUES (1,'كيف تبدأ التفكير بالإنجليزية','How to Start Thinking in English','كيف تبدأ التفكير بالإنجليزية','How to Start Thinking in English','توقف عن الترجمة في رأسك: تمارين عملية تدرّب دماغك على التفكير مباشرة بالإنجليزية.','Stop translating in your head: practical exercises that train your brain to think directly in English.','توقف عن الترجمة في رأسك: تمارين عملية تدرّب دماغك على التفكير مباشرة بالإنجليزية.','Stop translating in your head: practical exercises that train your brain to think directly in English.','how-to-start-thinking-in-english','article-1.svg','فريق أب سكيلز','Upskills Team',CURDATE(),1,0,NOW(),NOW());
INSERT INTO articles (id,titre_ar,titre_en,meta_title_ar,meta_title_en,description_ar,description_en,description_short_ar,description_short_en,slug,image,author_ar,author_en,published_date,is_active,views_count,created_at,updated_at) VALUES (2,'دليل كامل لكتابة المهمة الثانية في الآيلتس','IELTS Writing Task 2: A Complete Guide','دليل كامل لكتابة المهمة الثانية في الآيلتس','IELTS Writing Task 2: A Complete Guide','بنية المقال، إدارة الوقت، ومعايير التقييم — كل ما تحتاجه لمهمة الكتابة الثانية.','Essay structure, time management and band descriptors — everything you need for Task 2.','بنية المقال، إدارة الوقت، ومعايير التقييم — كل ما تحتاجه لمهمة الكتابة الثانية.','Essay structure, time management and band descriptors — everything you need for Task 2.','ielts-writing-task-2-complete-guide','article-2.svg','فريق أب سكيلز','Upskills Team',CURDATE(),1,0,NOW(),NOW());
